export T="$TMPDIR/i041"; python3 - <<'EOF'
import re, os, sys
OUT=os.environ["T"]
EXTS=(".c",".h")
roots=["drivers","net","kernel","mm","fs","block","crypto","lib","security","ipc","sound","virt"]
files=[]
for r in roots:
    for dp,dn,fn in os.walk(r):
        for f in fn:
            if f.endswith(EXTS): files.append(os.path.join(dp,f))
def read(p):
    with open(p,encoding="utf-8",errors="replace") as fh: return fh.read().split("\n")

def func_body_span(lines, name):
    # find definition (not call) of function `name`; return (start_line,end_line) inclusive, 1-based
    pat = re.compile(r'^(?:[A-Za-z_][A-Za-z0-9_ \t\*&]*?)\b'+re.escape(name)+r'\s*\(')
    for idx,l in enumerate(lines):
        m=pat.match(l)
        if not m: continue
        # ensure it's a definition: has '{' somewhere after on same or following lines before ';'
        j=idx; depth=0; started=False; buf=""
        while j<len(lines) and j<idx+12:
            buf+=lines[j]
            if ";" in lines[j] and "{" not in lines[j]:
                break
            if "{" in lines[j]:
                started=True; break
            j+=1
        if not started: continue
        # walk braces from line idx
        depth=0; started=False
        for k in range(idx,len(lines)):
            for ch in lines[k]:
                if ch=="{":
                    depth+=1; started=True
                elif ch=="}":
                    depth-=1
                    if started and depth==0:
                        return (idx+1,k+1)
    return None

lock_re = re.compile(r'\bspin_(?:un)?lock(?:_irqsave|_irqrestore|_irq|_bh|_nosync)?\s*\(\s*&?\s*([^),]+)')
def lock_kind(call):
    if call.startswith("spin_unlock"): return "unlock"
    if "_bh" in call: return "bh"
    if "_irqsave" in call or "_irqrestore" in call: return "irqsave"
    if "_irq" in call: return "irq"
    return "plain"

softirq_funcs={}  # (file, func) -> {"kind":..., "lines": span}
tasklet_sites=[]
for p in files:
    lines=read(p)
    for i,l in enumerate(lines,1):
        if re.search(r'\btasklet_init\s*\(', l) or re.search(r'\btasklet_setup\s*\(', l) or "DECLARE_TASKLET" in l:
            tasklet_sites.append((p,i,l.strip()))
        for m in re.finditer(r'netif_napi_add(?:_tx|_rx|_tx_weight|_rx_weight)?\s*\(', l):
            tasklet_sites.append((p,i,l.strip()))

# extract callback/poll names
cb_entries=[]  # (file, cbname, kind, regline, regtext)
for p,i,l in tasklet_sites:
    is_tasklet = ("tasklet_init" in l) or ("tasklet_setup" in l) or ("DECLARE_TASKLET" in l)
    is_napi = "netif_napi_add" in l
    if is_tasklet:
        # callback: tasklet_init(t, func, data) / tasklet_setup(t, func) / DECLARE_TASKLET(name, func, data)
        mm=re.search(r'tasklet_init\s*\(\s*[^,]+,\s*([A-Za-z_][A-Za-z0-9_]*)\s*,', l)
        if not mm: mm=re.search(r'tasklet_setup\s*\(\s*[^,]+,\s*([A-Za-z_][A-Za-z0-9_]*)\s*\)', l)
        if not mm: mm=re.search(r'DECLARE_TASKLET(?:_DISABLED)?\s*\(\s*[A-Za-z_][A-Za-z0-9_]*\s*,\s*([A-Za-z_][A-Za-z0-9_]*)\s*,', l)
        if mm: cb_entries.append((p,mm.group(1),"tasklet",i,l))
    if is_napi:
        # find poll fn: last identifier before closing paren of netif_napi_add
        # gather full call across lines
        j=i-1; buf=lines[j]
        depth=buf.count("(")-buf.count(")")
        while depth>0 and j+1<len(lines) and j<i+8:
            j+=1; buf+=" "+lines[j]; depth=buf.count("(")-buf.count(")")
        args=buf[buf.find("netif_napi_add"):]
        # poll is typically last arg or second-to-last if weight given; try identifiers
        ids=re.findall(r'([A-Za-z_][A-Za-z0-9_]*)\s*[,)]', args)
        # heuristics: poll function usually name containing 'poll' or 'napi' or equal to file prefix
        cand=[x for x in ids if x not in ("netif_napi_add","netif_napi_add_tx","netif_napi_add_rx","netif_napi_add_tx_weight","netif_napi_add_rx_weight","GFP_KERNEL")]
        polly=[x for x in cand if ("poll" in x.lower() or "napi" in x.lower())]
        pick = polly[-1] if polly else (cand[-1] if cand else None)
        if pick: cb_entries.append((p,pick,"napi_poll",i,buf.strip()))

print("callback entries:",len(cb_entries))
with open(os.path.join(OUT,"cbs.txt"),"w") as f:
    for p,cb,kind,rl,txt in cb_entries:
        f.write(f"{p}|{cb}|{kind}|{rl}|{txt[:160]}\n")

# map: file -> set of softirq func names
from collections import defaultdict
byfile=defaultdict(set)
for p,cb,kind,rl,txt in cb_entries:
    byfile[p].add(cb)

# extract locks inside softirq callback bodies (direct body only)
soft_locks={}   # (file, lockexpr, kind) -> (func, span, linenum)
for p,cbs in byfile.items():
    lines=read(p)
    for cb in cbs:
        span=func_body_span(lines,cb)
        if not span: continue
        s,e=span
        for k in range(s-1,e):
            for m in re.finditer(r'\bspin_(?:un)?lock(?:_irqsave|_irqrestore|_irq|_bh|_nosync)?\s*\(\s*&?\s*([^),]+)', lines[k]):
                call=lines[k].strip()
                # record only actual locks (skip unlock) with kind
                if lines[k].strip().startswith("spin_unlock"): continue
                expr=m.group(1).strip()
                soft_locks[(p,expr,lock_kind(lines[k]))]=(cb,(s,e),k+1,lines[k].strip())
print("softirq-side lock usages:",len(soft_locks))
with open(os.path.join(OUT,"soft_locks.txt"),"w") as f:
    for (p,expr,kind),v in sorted(soft_locks.items()):
        f.write(f"{p}|{v[0]}|{expr}|{kind}|{v[2]}|{v[3]}\n")
from collections import Counter
print(Counter(k[2] for k in soft_locks).most_common())
EOF

